classes:
class Animal:
    def __init__(self, name):
        self.__name = name
    def get_name(self):
        return self.__name
    def speak(self):
        return '...'
    def __str__(self):
        return 'Animal ' + self.__name
class Dog(Animal):
    def __init__(self, name):
        super().__init__(name)
    def speak(self):
        return 'Woof'
d = Dog('Rex')
print(d.get_name(), d.speak(), str(d), isinstance(d, Animal))
class MyErr(Exception):
    pass
try:
